descriptor.templateCss:
.sem-timer {
  height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 14px;
  font-family: Roboto, Arial, sans-serif;
  color: rgba(0, 0, 0, 0.87);
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field label {
  font-size: 12px;
  font-weight: 500;
  color: rgba(0, 0, 0, 0.62);
}

.field select,
.field input {
  box-sizing: border-box;
  width: 100%;
  height: 36px;
  border: 1px solid rgba(0, 0, 0, 0.22);
  border-radius: 4px;
  padding: 6px 8px;
  background: #fff;
  color: rgba(0, 0, 0, 0.87);
  font-size: 14px;
}

.buttons {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 8px;
}

.buttons button {
  min-height: 36px;
  border: 1px solid rgba(0, 0, 0, 0.18);
  border-radius: 4px;
  background: #fff;
  color: rgba(0, 0, 0, 0.78);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}

.buttons button.primary {
  border-color: #1565c0;
  background: #1565c0;
  color: #fff;
}

.buttons button:disabled,
.field select:disabled,
.field input:disabled {
  cursor: default;
  opacity: 0.55;
}

.status {
  min-height: 58px;
  overflow: auto;
  border-left: 4px solid #9e9e9e;
  border-radius: 4px;
  padding: 8px 10px;
  background: #f7f7f7;
  font-size: 13px;
  line-height: 1.35;
}

.status.ok {
  border-left-color: #2e7d32;
  background: #eef7ef;
}

.status.error {
  border-left-color: #c62828;
  background: #fff1f1;
}

.status.busy {
  border-left-color: #ef6c00;
  background: #fff6e8;
}

.status pre {
  margin: 8px 0 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 12px;
}

@media (max-width: 420px) {
  .buttons {
    grid-template-columns: 1fr;
  }
}

descriptor.controllerScript:
self.onInit = function() {
  var $scope = self.ctx.$scope;
  var settings = self.ctx.settings || {};
  var requestTimeout = settings.requestTimeout || 30000;

  $scope.action = settings.defaultAction || 'off';
  $scope.targetDateTime = '';
  $scope.minDateTime = toLocalInputValue(new Date());
  $scope.busy = false;
  $scope.statusKind = 'idle';
  $scope.statusText = 'Tria una data i hora i prem Programar.';
  $scope.lastResponse = '';

  function pad(value) {
    return String(value).padStart(2, '0');
  }

  function toLocalInputValue(date) {
    return date.getFullYear() + '-' +
      pad(date.getMonth() + 1) + '-' +
      pad(date.getDate()) + 'T' +
      pad(date.getHours()) + ':' +
      pad(date.getMinutes());
  }

  function toSem6000Iso(value) {
    if (!value) {
      return null;
    }
    var date = new Date(value);
    if (isNaN(date.getTime())) {
      return null;
    }
    return date.getFullYear() + '-' +
      pad(date.getMonth() + 1) + '-' +
      pad(date.getDate()) + 'T' +
      pad(date.getHours()) + ':' +
      pad(date.getMinutes()) + ':00';
  }

  function setStatus(kind, text, response) {
    $scope.statusKind = kind;
    $scope.statusText = text;
    $scope.lastResponse = response || '';
    self.ctx.detectChanges();
  }

  function stringify(value) {
    try {
      return JSON.stringify(value, null, 2);
    } catch (e) {
      return String(value);
    }
  }

  function sendRpc(method, params, successText) {
    $scope.busy = true;
    setStatus('busy', 'Enviant RPC ' + method + '...', '');

    self.ctx.controlApi.sendTwoWayCommand(method, params || {}, requestTimeout).subscribe(
      function(response) {
        $scope.busy = false;
        setStatus('ok', successText, stringify(response));
      },
      function(rejection) {
        $scope.busy = false;
        var detail = 'RPC fallit';
        if (rejection) {
          detail = rejection.statusText || rejection.message || rejection.error || detail;
        }
        setStatus('error', detail, stringify(rejection));
      }
    );
  }

  $scope.scheduleTimer = function($event) {
    if ($event && $event.preventDefault) {
      $event.preventDefault();
    }

    var target = toSem6000Iso($scope.targetDateTime);
    if (!target) {
      setStatus('error', 'Data i hora no valides.', '');
      return;
    }

    sendRpc(
      'setTimer',
      {
        action: $scope.action,
        target_isodatetime: target
      },
      'Timer programat per ' + target + ' amb accio ' + $scope.action + '.'
    );
  };

  $scope.refreshTimer = function() {
    sendRpc('getTimer', {}, 'Estat del timer actualitzat.');
  };

  $scope.resetTimer = function() {
    sendRpc('resetTimer', {}, 'Timer cancel.lat.');
  };
};

self.typeParameters = function() {
  return {
    maxDatasources: 0,
    singleEntity: true,
    previewWidth: '420px',
    previewHeight: '320px',
    embedTitlePanel: true
  };
};

self.onDestroy = function() {
};
